let state,storageError=false;
try{state=JSON.parse(localStorage.getItem('truelens-workspace-v1'));if(!state||state.version!==1||!Array.isArray(state.projects))state=seed();}catch{state=seed();storageError=true;}
let selected=state.selected||state.projects[0]?.id,page='overview',search='',filter='All',homeRendered=false,workflowStep=0,audience='consultancies';
const project=()=>state.projects.find(p=>p.id===selected)||state.projects[0];
const initials=name=>String(name).split(' ').map(x=>x[0]).join('').slice(0,2).toUpperCase();
const date=value=>new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const timestamp=value=>new Date(value).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const bytes=n=>n>1048576?`${(n/1048576).toFixed(1)} MB`:`${Math.max(1,Math.round(n/1024))} KB`;
const openIssues=p=>p.issues.filter(x=>x.status!=='Resolved');
function save(){try{state.selected=selected;localStorage.setItem('truelens-workspace-v1',JSON.stringify(state));return true;}catch{storageError=true;toast('Browser storage is full or unavailable. Export a backup to retain this session.');return false;}}
save();
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function log(p,text){p.activity.unshift({id:uid(),date:new Date().toISOString(),text,actor:'You'});}
function progress(p){return completeness(p.documents,requirements);}
function download(content,name,type='text/plain'){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function openModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${e(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.showModal();}
modal.addEventListener('click',ev=>{if(ev.target===modal){const r=modal.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)modal.close();}});
function empty(title,text,action,label){return `<div class="empty"><div class="icon-box">${icon('folder')}</div><h3>${e(title)}</h3><p>${e(text)}</p>${action?`<button class="btn small" data-action="${action}">${e(label)}</button>`:''}</div>`;}

