function workflowArt(i){return `<div class="workflow-card"><div class="wide-icon">${icon(['upload','eye','shield'][i])}</div><h3>${['Everything in its place.','The gaps come into focus.','Your decision. On record.'][i]}</h3><p>${['Organised from the very first document.','A clear view of evidence still to add.','A review journey you can follow.'][i]}</p>${i===0?`<div class="doc-stack">${icon('file')}Fire strategy.pdf<small>P01</small></div><div class="doc-stack">${icon('file')}Design drawings.pdf<small>P03</small></div><span class="tag blue">One structured document register</span>`:i===1?`<div class="assessment-main"><strong>75<span>%</span></strong><span>Sample coverage</span></div><div class="bar"><span style="width:75%"></span></div><span class="tag medium">2 evidence categories to add</span>`:`<div class="doc-stack">${icon('circlecheck')}Review note recorded<small>Today</small></div><div class="doc-stack">${icon('users')}Reviewer assigned<small>SM</small></div><span class="tag blue">A traceable record of each step</span>`}</div>`;}
const audiences={consultancies:{title:'Turn expertise into a clearer client deliverable.',text:'Make your assurance process visible. Give each project a structured review record and keep your team focused on the decisions that matter.',benefits:['A consistent workflow across client projects','Clear ownership for every review action','Exportable evidence and action registers']},developers:{title:'Know where your submission stands.',text:'See what has been added, what needs attention and who is taking it forward, before gaps become programme uncertainty.',benefits:['A portfolio view of project evidence','A clear picture of outstanding actions','Better informed conversations with your team']},contractors:{title:'Keep information moving with the programme.',text:'Bring documentation and actions together so your team can see what is needed and keep the review process coordinated.',benefits:['Document ownership and revision tracking','A visible list of review priorities','A record of changes and decisions']},designers:{title:'Give your design information a clearer path.',text:'Keep technical evidence organised and give reviewers a structured way to record questions and close the loop.',benefits:['A coordinated document register','Clear feedback with a responsible reviewer','Traceable responses to review findings']}};
function audienceContent(id){const x=audiences[id];return `<div class="icon-box">${icon({consultancies:'users',developers:'building',contractors:'layers',designers:'edit'}[id])}</div><h3>${x.title}</h3><p>${x.text}</p><div class="benefit-list">${x.benefits.map(b=>`<div>${icon('check')}${b}</div>`).join('')}</div>`;}

const navs=[['overview','grid','Overview'],['projects','folder','Projects'],['documents','file','Documents'],['actions','alert','Review actions'],['evidence','layers','Evidence map'],['activity','clock','Activity']];
function workspace(){
homeRendered=false;
const p=project(),valid=navs.find(n=>n[0]===page);if(!valid){page='overview';}
app.innerHTML=`<div class="workspace"><aside class="sidebar">${brand()}<div class="workspace-label">Your workspace</div><nav class="side-nav" aria-label="Workspace navigation">${navs.map(([id,ic,label])=>`<a href="#/app/${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='actions'&&p?`<span class="count">${openIssues(p).length}</span>`:''}</a>`).join('')}</nav><div class="side-bottom"><div class="sandbox-card"><strong>A clearer view starts here.</strong><p>Explore with sample projects or create your own.</p><button class="text-btn" data-action="about">About this workspace</button></div><div class="user"><span class="avatar">YW</span><div><strong>Your workspace</strong><small>Saved on this device</small></div><button class="icon-btn" data-action="settings" aria-label="Workspace settings" style="margin-left:auto">${icon('info')}</button></div></div></aside><div class="workspace-main"><header class="workspace-topbar"><button class="menu-button" data-action="workspace-nav" aria-label="Toggle workspace navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span>Workspace</span><span>/</span><strong>${valid?valid[2]:'Overview'}</strong></div><div class="topbar-right"><a href="#/">Back to website</a><span class="tag blue">Interactive preview</span><button class="icon-btn" data-action="help" aria-label="Workspace help">${icon('info')}</button></div></header><main id="main" class="work-content">${storageError?'<div class="storage-alert">Browser storage is unavailable. Export a workspace backup before leaving this session.</div>':''}${workspacePage()}</main></div></div>`;
}
function title(name,sub,actions=''){return `<div class="work-title"><div><h1>${name}</h1><p>${sub}</p></div><div class="work-actions">${actions}</div></div>`;}
function projectSelect(){return `<div class="focus-project"><label for="project-focus">Current project <select id="project-focus" class="select-control">${state.projects.map(p=>`<option value="${e(p.id)}" ${p.id===project()?.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><span>${e(project()?.stage||'')} · ${e(project()?.client||'')}</span></div>`;}
function projectItem(p){const x=progress(p);return `<a class="project-item" href="#/app/evidence" data-project="${e(p.id)}"><div class="project-icon">${icon('building')}</div><div class="project-info"><h3>${e(p.name)}</h3><p>${e(p.client)} · ${e(p.stage)}</p></div><div class="project-progress"><span>${x.percent}% coverage</span><div class="bar"><span style="width:${x.percent}%"></span></div></div>${icon('chevron')}</a>`;}
function activityItem(a,projectName=''){return `<div class="activity-item"><div class="activity-symbol">${icon('clock')}</div><div><strong>${e(a.text)}</strong><p>${e(a.actor)}${projectName?' · '+e(projectName):''} · ${timestamp(a.date)}</p></div></div>`;}
function workspacePage(){
const p=project();
if(page==='overview'){
 const docs=state.projects.reduce((n,x)=>n+x.documents.length,0),issues=state.projects.reduce((n,x)=>n+openIssues(x).length,0),coverage=state.projects.length?Math.round(state.projects.reduce((n,x)=>n+progress(x).percent,0)/state.projects.length):0;
 const activity=state.projects.flatMap(x=>x.activity.map(a=>({...a,project:x.name}))).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
 return `${title('A clearer view.','Your projects, evidence and review priorities in one place.',`<button class="btn secondary small" data-action="backup">${icon('download')}Export backup</button><button class="btn small" data-action="new-project">${icon('plus')}New project</button>`)}<div class="demo-banner">${icon('info')}<span><strong>Make yourself at home.</strong> Sample projects are illustrative. Your changes stay in this browser.</span></div><div class="metrics">${[['Active projects',state.projects.length,'Across your workspace','building'],['Documents',docs,'In your document registers','file'],['Open actions',issues,'Awaiting a professional decision','alert'],['Evidence coverage',coverage+'%','Average across all projects','layers']].map(([label,value,hint,ic])=>`<div class="metric"><div class="metric-label">${label}${icon(ic)}</div><strong>${value}</strong><small>${hint}</small></div>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Your projects</h2><p>A shared structure for every submission</p></div><a class="text-btn" href="#/app/projects">View all projects</a></div>${state.projects.length?state.projects.slice(0,5).map(projectItem).join(''):empty('Your first project starts here.','Add a project to organise its evidence and review actions.','new-project','Create project')}</section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><a class="text-btn" href="#/app/activity">View activity</a></div><div class="panel-body" style="padding-top:6px;padding-bottom:9px">${activity.length?activity.map(a=>activityItem(a,a.project)).join(''):'<p class="activity-empty">Your project history will appear here.</p>'}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Bring your next submission into focus.</h2><p>A document register, an evidence map and a clear review journey.</p></div><button class="btn secondary small" data-action="new-project">Create a project</button></div><div class="panel-body"><div class="benefit-list" style="margin-top:0;display:flex;flex-wrap:wrap;gap:20px 35px"><div>${icon('file')}Organise the evidence</div><div>${icon('users')}Assign the right expertise</div><div>${icon('shield')}Record the decisions</div></div></div></section>`;
}
if(page==='projects')return `${title('Your projects.','A consistent workspace for every submission.',`<button class="btn small" data-action="new-project">${icon('plus')}New project</button>`)}${toolbar('Search projects…',['All','Residential','Commercial','Infrastructure'])}<div class="project-grid" id="results">${state.projects.filter(p=>filter==='All'||p.type===filter).map(p=>{const x=progress(p);return `<a class="project-card" data-search="${e((p.name+' '+p.client).toLowerCase())}" href="#/app/evidence" data-project="${e(p.id)}"><div class="project-card-top"><div class="project-icon">${icon('building')}</div><span class="tag ${p.sample?'':'blue'}">${p.sample?'Sample project':e(p.type)}</span></div><div><h2>${e(p.name)}</h2><p>${e(p.client)}</p></div><div class="project-meta"><span>${e(p.stage)}</span><span>·</span><span>${p.documents.length} documents</span><span>·</span><span>${openIssues(p).length} open actions</span></div><div class="project-card-bottom"><span>${x.percent}% evidence coverage</span><div class="bar"><span style="width:${x.percent}%"></span></div></div></a>`;}).join('')}</div><div id="search-empty" hidden>${empty('No projects match.','Try another search or create a new project.','new-project','New project')}</div>`;
if(!p)return `${title('Create your first project.','Bring documents and review decisions into focus.')} ${empty('A fresh start.','Create a project to start building your document register.','new-project','Create project')}`;
if(page==='documents')return `${title('Documents. Organised.','Every document, owner and revision in one register.',`<button class="btn secondary small" data-action="export-documents">${icon('download')}Export register</button><button class="btn small" data-action="upload">${icon('upload')}Add documents</button>`)}${projectSelect()}${toolbar('Search documents…',['All','Sample','Uploaded'])}<section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>DOCUMENT</th><th>CATEGORY</th><th>OWNER</th><th>REVISION</th><th>ADDED</th><th>ACTIONS</th></tr></thead><tbody id="results">${p.documents.filter(d=>filter==='All'||(filter==='Sample'?d.sample:!d.sample)).map(d=>`<tr data-search="${e((d.name+' '+d.category+' '+d.owner).toLowerCase())}"><td><div class="doc-name">${icon('file')}<div>${e(d.name)}<small>${d.sample?'Illustrative record':bytes(d.size)}</small></div></div></td><td><span class="tag">${e(d.category)}</span></td><td>${e(d.owner)}</td><td>${e(d.revision)}</td><td>${date(d.date)}</td><td><div class="row-actions"><button class="icon-btn" data-action="view-document" data-id="${e(d.id)}" aria-label="View ${e(d.name)}">${icon('eye')}</button><button class="icon-btn" data-action="edit-document" data-id="${e(d.id)}" aria-label="Edit ${e(d.name)}">${icon('edit')}</button>${!d.sample?`<button class="icon-btn" data-action="download-document" data-id="${e(d.id)}" aria-label="Download ${e(d.name)}">${icon('download')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div id="search-empty" hidden>${empty('Your document register is ready.','Add documents or adjust your search to see records here.','upload','Add documents')}</div></section><p class="hint" style="margin-top:15px">Uploaded files stay in this browser. Evidence checks use categories, not document contents.</p>`;
if(page==='actions')return `${title('Turn insight into action.','Clear priorities. Named reviewers. A traceable response.',`<button class="btn secondary small" data-action="export-actions">${icon('download')}Export actions</button><button class="btn small" data-action="new-action">${icon('plus')}Add action</button>`)}${projectSelect()}${toolbar('Search actions…',['All','Open','In review','Resolved'])}<div class="issue-list" id="results">${p.issues.filter(x=>filter==='All'||x.status===filter).map(x=>`<article class="issue-card" data-search="${e((x.title+' '+x.owner+' '+x.document).toLowerCase())}"><div><div class="issue-meta"><span class="tag ${x.severity.toLowerCase()}">${e(x.severity)}</span><span class="tag ${x.status==='Resolved'?'green':''}">${e(x.status)}</span><span class="ref">${e(x.category)}</span></div><h3>${e(x.title)}</h3><p>${e(x.document)}</p><div class="issue-card-bottom"><span class="avatar">${e(initials(x.owner))}</span><span>${e(x.owner)}</span><span>${e(x.reference||'Reviewer action')}</span></div></div><button class="btn secondary small" data-action="review-action" data-id="${e(x.id)}">Review action</button></article>`).join('')}</div><div id="search-empty" hidden>${empty('Nothing waiting here.','Adjust your filters, run an evidence check or add a review action.','new-action','Add action')}</div>`;
if(page==='evidence'){
 const x=progress(p);return `${title('The full picture.','See the evidence you have and what still needs attention.',`<button class="btn secondary small" data-action="report">${icon('download')}Export report</button><button class="btn small" data-action="run-check">${icon('layers')}Check evidence</button>`)}${projectSelect()}<div class="check-summary"><div><h2>Your evidence, in focus.</h2><p>${x.covered} of ${x.total} illustrative categories have document records. Coverage does not assess document quality, completeness or regulatory compliance.</p></div><div><strong>${x.percent}%</strong><small>Category coverage</small></div></div><div class="evidence-grid">${requirements.map(r=>{const docs=p.documents.filter(d=>d.category===r.category);return `<article class="evidence-card ${docs.length?'':'missing'}">${icon(docs.length?'circlecheck':'alert')}<div><h3>${e(r.name)}</h3><p>${e(r.detail)}</p>${docs.length?`<span class="tag green">${docs.length} document${docs.length===1?'':'s'} added · requires review</span>`:`<button class="tag medium" data-action="upload" data-category="${e(r.category)}">No document added · add evidence</button>`}</div></article>`;}).join('')}</div><p class="hint" style="margin-top:20px">This is an illustrative planning checklist, not an exhaustive regulatory checklist. Confirm the evidence and requirements for your building and application with a competent professional. <a href="https://www.gov.uk/guidance/applying-for-building-control-approval-for-a-higher-risk-building" target="_blank" rel="noopener" style="color:var(--blue);text-decoration:underline">View government guidance</a>.</p>`;
}
if(page==='activity')return `${title('Every step. On record.','Your project’s documents, reviews and decisions.',`<button class="btn secondary small" data-action="export-activity">${icon('download')}Export activity</button>`)}${projectSelect()}<section class="panel"><div class="panel-head"><div><h2>Project activity</h2><p>A browser-local activity record · ${p.activity.length} events</p></div><span class="tag blue">${e(p.name)}</span></div><div class="timeline">${p.activity.map(a=>activityItem(a)).join('')}</div></section><p class="hint" style="margin-top:15px">This local history is editable browser data. It is not an immutable or independently certified audit record.</p>`;
return '';
}
function toolbar(placeholder,filters){return `<div class="toolbar"><div class="search-box">${icon('search')}<input id="search" type="search" value="${e(search)}" placeholder="${e(placeholder)}" aria-label="${e(placeholder.replace('…',''))}"></div><div class="filter-tabs" aria-label="Filter records">${filters.map(f=>`<button data-action="filter" data-filter="${e(f)}" aria-pressed="${filter===f}" class="${filter===f?'active':''}">${e(f)}</button>`).join('')}</div></div>`;}
function applySearch(){const rows=app.querySelectorAll('#results [data-search]');let count=0;rows.forEach(row=>{row.hidden=!row.dataset.search.includes(search.toLowerCase());if(!row.hidden)count++;});const empty=app.querySelector('#search-empty');if(empty)empty.hidden=count!==0;}
function render(){workspace();applySearch();}
function route(){
 const hash=location.hash||'#/';
 if(hash.startsWith('#/app')){const next=hash.split('/')[2]||'overview';if(next!==page){search='';filter='All';}page=next;render();window.scrollTo(0,0);}
 else{if(!homeRendered){landing();window.scrollTo(0,0);}if(hash!=='#/'&&hash!=='#'){setTimeout(()=>document.getElementById(hash.slice(1))?.scrollIntoView(),0);}}
}
window.addEventListener('hashchange',route);

function newProjectModal(){openModal('A new perspective.',`<p>Create a project workspace for your documents, evidence and review decisions.</p><form data-form="project"><div class="form-grid"><label class="field full">Project name<input name="name" placeholder="e.g. Riverside Quarter" required maxlength="100" autofocus></label><label class="field full">Client / organisation<input name="client" placeholder="Organisation name" maxlength="100"></label><label class="field">Project type<select name="type"><option>Residential</option><option>Commercial</option><option>Infrastructure</option><option>Other</option></select></label><label class="field">Review stage<select name="stage"><option>Gateway 2</option><option>Design review</option><option>Gateway 3</option><option>Building assessment</option><option>Other</option></select></label></div><p class="hint" style="margin-top:18px">This workspace saves on your current device. Start with non-sensitive project information.</p><div class="form-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" type="submit">Create project</button></div></form>`);}
const categories=()=>[...requirements.map(x=>x.category),'Other'];
function uploadModal(category){openModal('Bring your evidence together.',`<p>Add files to ${e(project().name)}. Files are stored on this device and are not sent for analysis.</p><form data-form="upload"><div class="dropzone" id="dropzone">${icon('upload')}<strong>Choose documents or drop them here</strong><span class="hint">PDF, DOCX, XLSX, CSV, TXT, PNG or JPEG · up to 10 MB each</span><input type="file" id="upload-files" name="files" multiple required accept=".pdf,.docx,.xlsx,.csv,.txt,.png,.jpg,.jpeg" aria-label="Choose documents"></div><div class="form-grid"><label class="field full">Evidence category<select name="category">${categories().map(c=>`<option ${c===category?'selected':''}>${e(c)}</option>`).join('')}</select></label><label class="field">Document owner<input name="owner" placeholder="Reviewer or team" value="You" maxlength="100" required></label><label class="field">Revision<input name="revision" placeholder="e.g. P01" value="P01" maxlength="30" required></label></div><div class="form-error" id="form-error" role="alert"></div><div class="form-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" type="submit">Add to register</button></div></form>`);
 const drop=modal.querySelector('#dropzone');drop.addEventListener('dragover',ev=>{ev.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',ev=>{ev.preventDefault();drop.classList.remove('drag');const input=modal.querySelector('#upload-files');input.files=ev.dataTransfer.files;});}
function actionModal(action){
 const x=action||{title:'',description:'',severity:'Medium',owner:'You',status:'Open',category:'Other',document:'Submission pack',note:''};
 openModal(action?'A clear next step.':'Add a review action.',`${action?`<div class="issue-meta"><span class="tag ${x.severity.toLowerCase()}">${e(x.severity)} priority</span><span class="tag">${e(x.category)}</span></div><div class="issue-detail"><strong style="color:var(--ink)">${e(x.title)}</strong><br>${e(x.description)}</div><p class="hint" style="margin-bottom:18px">${e(x.document)} · ${e(x.reference||'Reviewer action')}</p>`:'<p>Capture a question, missing item or review decision and assign a responsible person.</p>'}<form data-form="action" data-id="${e(x.id||'')}"><div class="form-grid">${!action?`<label class="field full">Action title<input name="title" required maxlength="150" placeholder="What needs to be addressed?"></label><label class="field full">Description<textarea name="description" required maxlength="3000" placeholder="Describe the evidence or decision required."></textarea></label><label class="field">Category<select name="category">${categories().map(c=>`<option>${e(c)}</option>`).join('')}</select></label><label class="field">Priority<select name="severity"><option>High</option><option selected>Medium</option><option>Low</option></select></label>`:''}<label class="field">Assigned reviewer<input name="owner" required value="${e(x.owner)}" maxlength="100"></label><label class="field">Status<select name="status">${['Open','In review','Resolved'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field full">Review note / decision<textarea name="note" maxlength="3000" placeholder="Record your response. A note is required to resolve an action.">${e(x.note)}</textarea></label></div><div class="form-error" id="form-error" role="alert"></div><div class="form-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" type="submit">Save action</button></div></form>`);
}
function db(){return new Promise((resolve,reject)=>{const request=indexedDB.open('truelens-files-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('files');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function fileStore(mode,key,file){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('files',mode),store=tx.objectStore('files'),req=file?store.put(file,key):store.get(key);let result;req.onsuccess=()=>result=req.result;tx.oncomplete=()=>{database.close();resolve(result);};tx.onerror=()=>{database.close();reject(tx.error);};});}
async function showDocument(id){const d=project().documents.find(x=>String(x.id)===id);if(!d)return;
 if(d.sample){openModal(d.name,`<span class="tag blue">Illustrative document record</span><div class="status-box"><h3>This is a sample.</h3><p>It demonstrates a document’s position in the submission workflow. No source document or technical analysis is attached.</p></div><div class="form-grid"><div class="field">Category<span class="hint">${e(d.category)}</span></div><div class="field">Owner<span class="hint">${e(d.owner)}</span></div><div class="field">Revision<span class="hint">${e(d.revision)}</span></div><div class="field">Added<span class="hint">${date(d.date)}</span></div></div><div class="form-footer"><button class="btn secondary" data-action="close-modal">Close</button><button class="btn" data-action="edit-document" data-id="${e(d.id)}">Edit record</button></div>`);return;}
 try{const file=await fileStore('readonly',d.id);if(!file)throw Error('File not found');openModal(d.name,`<div class="issue-meta"><span class="tag">${e(d.category)}</span><span class="tag blue">Revision ${e(d.revision)}</span></div><p style="margin-top:18px">Stored on this device · ${bytes(d.size)} · Owner: ${e(d.owner)}</p>${/\.(txt|csv)$/i.test(d.name)?`<pre class="document-text">${e((await file.text()).slice(0,30000))}</pre>`:'<div class="status-box"><h3>Your document is ready to download.</h3><p>Open the original file in your preferred document viewer to review its technical content.</p></div>'}<div class="form-footer"><button class="btn secondary" data-action="close-modal">Close</button><button class="btn" data-action="download-document" data-id="${e(d.id)}">${icon('download')}Download file</button></div>`);}catch{toast('The file is unavailable in this browser. Add the source document again.');}}
function editDocument(id){const d=project().documents.find(x=>String(x.id)===id);if(modal.open)modal.close();openModal('Update document record.',`<p>${e(d.name)}</p><form data-form="document" data-id="${e(d.id)}"><div class="form-grid"><label class="field full">Evidence category<select name="category">${categories().map(c=>`<option ${c===d.category?'selected':''}>${e(c)}</option>`).join('')}</select></label><label class="field">Owner<input name="owner" required value="${e(d.owner)}" maxlength="100"></label><label class="field">Revision<input name="revision" required value="${e(d.revision)}" maxlength="30"></label></div><p class="hint" style="margin-top:18px">This updates the register only. Upload a new file to record a new source document.</p><div class="form-footer"><button type="button" class="btn secondary" data-action="close-modal">Cancel</button><button class="btn" type="submit">Save changes</button></div></form>`);}
function runCheck(){const p=project(),missing=requirements.filter(r=>!p.documents.some(d=>d.category===r.category));let added=0,reopened=0;for(const r of missing){let existing=p.issues.find(x=>x.coverageCategory===r.category);if(existing){if(existing.status==='Resolved'){existing.status='Open';reopened++;}}else{p.issues.push({id:uid(),title:`Add evidence: ${r.name.toLowerCase()}`,description:r.detail,severity:['Fire safety','Structural','Reporting'].includes(r.category)?'High':'Medium',category:r.category,document:'Submission pack',reference:'Evidence coverage check',owner:'Unassigned',status:'Open',note:'',coverageCategory:r.category});added++;}}
const x=progress(p);log(p,`Evidence category check completed: ${x.covered}/${x.total} categories present; ${added} actions added, ${reopened} reopened`);save();render();openModal('Your evidence check.',`<div class="check-summary"><div><h2>${x.covered} of ${x.total} categories present.</h2><p>This checks the document register only. It does not assess technical content or compliance.</p></div><div><strong>${x.percent}%</strong></div></div><p>${missing.length?`${missing.length} categories have no document records. ${added} new review actions added${reopened?`, ${reopened} reopened`:''}. Existing open coverage actions are retained.`:'Every illustrative category has a document record. Arrange professional review of the actual evidence.'}</p><div class="form-footer"><button class="btn secondary" data-action="close-modal">Close</button><a class="btn" href="#/app/actions" data-action="close-on-nav">View review actions</a></div>`);}
function exportReport(){const p=project(),x=progress(p);const content=`<!doctype html><html lang="en"><meta charset="utf-8"><title>${e(p.name)} — Evidence report</title><style>body{font:15px/1.65 Arial,sans-serif;max-width:1000px;margin:50px auto;padding:0 25px;color:#17213a}h1{font-size:36px;color:#2147ef}h2{margin-top:35px}table{border-collapse:collapse;width:100%;font-size:12px}th,td{border:1px solid #dce1eb;padding:10px;text-align:left}p{color:#52617a}footer{margin-top:35px;font-size:12px}@media print{body{margin:15mm}tr{break-inside:avoid}}</style><h1>Truelens · Evidence report</h1><h2>${e(p.name)}</h2><p>${e(p.client)} · ${e(p.stage)} · Exported ${e(new Date().toLocaleString('en-GB'))}</p><p><strong>${x.percent}% category coverage — ${x.covered} of ${x.total} illustrative categories.</strong><br>This report measures document category presence. It does not establish completeness, technical compliance or regulatory approval. ${p.sample?'This project includes illustrative sample information.':''}</p><h2>Evidence map</h2><table><tr><th>Category</th><th>Document records</th><th>Review requirement</th></tr>${requirements.map(r=>`<tr><td>${e(r.name)}</td><td>${p.documents.filter(d=>d.category===r.category).map(d=>e(d.name)).join('<br>')||'No document added'}</td><td>${e(r.detail)}</td></tr>`).join('')}</table><h2>Review actions</h2><table><tr><th>Action</th><th>Priority</th><th>Owner</th><th>Status</th><th>Review note</th></tr>${p.issues.map(i=>`<tr><td>${e(i.title)}</td><td>${e(i.severity)}</td><td>${e(i.owner)}</td><td>${e(i.status)}</td><td>${e(i.note)}</td></tr>`).join('')}</table><h2>Activity</h2><table><tr><th>When</th><th>Who</th><th>Event</th></tr>${p.activity.map(a=>`<tr><td>${e(new Date(a.date).toLocaleString('en-GB'))}</td><td>${e(a.actor)}</td><td>${e(a.text)}</td></tr>`).join('')}</table><footer>Generated from editable browser-local records. Not an immutable audit record. A competent professional must confirm the applicable requirements and assess the underlying evidence.</footer></html>`;
download(content,`${p.name.replace(/[^a-z0-9-]/gi,'-')}-evidence-report.html`,'text/html');log(p,'Evidence report exported');save();render();toast('Report exported. Open the HTML file to view or print to PDF.');}

document.addEventListener('click',async ev=>{
const target=ev.target.closest('[data-action],a[data-project]');if(!target)return;
if(target.dataset.project){selected=target.dataset.project;search='';filter='All';save();if(location.hash===target.getAttribute('href'))render();return;}
const action=target.dataset.action,id=target.dataset.id;
if(action==='close-modal'||action==='close-on-nav'){modal.close();return;}
if(action==='mobile-nav'){const nav=app.querySelector('.site-nav');const open=nav.classList.toggle('open');target.setAttribute('aria-expanded',open);return;}
if(action==='workspace-nav'){const open=app.querySelector('.workspace').classList.toggle('menu-open');target.setAttribute('aria-expanded',open);return;}
if(action==='workflow'){workflowStep=Number(target.dataset.step);app.querySelectorAll('.workflow-tab').forEach((b,i)=>{b.classList.toggle('active',i===workflowStep);b.setAttribute('aria-selected',i===workflowStep);});const panel=app.querySelector('#workflow-panel');panel.innerHTML=workflowArt(workflowStep);panel.setAttribute('aria-labelledby',`workflow-tab-${workflowStep}`);return;}
if(action==='audience'){audience=target.dataset.audience;app.querySelectorAll('[data-action=audience]').forEach(b=>{const active=b.dataset.audience===audience;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});app.querySelector('#audience-panel').innerHTML=audienceContent(audience);return;}
if(action==='filter'){filter=target.dataset.filter;render();return;}
if(action==='new-project'){newProjectModal();return;}
if(action==='upload'){uploadModal(target.dataset.category);return;}
if(action==='new-action'){actionModal();return;}
if(action==='review-action'){actionModal(project().issues.find(x=>x.id===id));return;}
if(action==='view-document'){await showDocument(id);return;}
if(action==='edit-document'){editDocument(id);return;}
if(action==='download-document'){const d=project().documents.find(x=>String(x.id)===id);try{const file=await fileStore('readonly',d.id);if(!file)throw Error();download(file,d.name);toast('Document downloaded.');}catch{toast('This file is not available in the current browser.');}return;}
if(action==='run-check'){runCheck();return;}
if(action==='report'){exportReport();return;}
if(action==='backup'){download(JSON.stringify(state,null,2),'truelens-workspace-backup.json','application/json');toast('Workspace records exported. Original file binaries are not included.');return;}
if(action==='export-documents'){const p=project();download(csv([['Project','Document','Category','Owner','Revision','Added','Sample'],...p.documents.map(d=>[p.name,d.name,d.category,d.owner,d.revision,d.date,d.sample?'Yes':'No'])]),'truelens-document-register.csv','text/csv');toast('Document register exported.');return;}
if(action==='export-actions'){const p=project();download(csv([['Project','Action','Description','Priority','Category','Document','Owner','Status','Decision'],...p.issues.map(x=>[p.name,x.title,x.description,x.severity,x.category,x.document,x.owner,x.status,x.note])]),'truelens-review-actions.csv','text/csv');toast('Review action register exported.');return;}
if(action==='export-activity'){const p=project();download(csv([['Project','Timestamp','Actor','Event'],...p.activity.map(x=>[p.name,x.date,x.actor,x.text])]),'truelens-activity.csv','text/csv');toast('Activity exported.');return;}
if(action==='about'||action==='help'){openModal('A workspace with perspective.',`<p>Explore the submission journey using the sample projects, or create a project of your own.</p><div class="benefit-list"><div>${icon('folder')}Create and organise projects.</div><div>${icon('file')}Add files, owners and revision records.</div><div>${icon('layers')}Check illustrative evidence category coverage.</div><div>${icon('users')}Assign review actions and record decisions.</div><div>${icon('download')}Export registers, reports and record backups.</div></div><div class="status-box" style="margin-top:25px"><h3>About this version</h3><p>Records and files are saved in this browser. AI document analysis, shared accounts, cloud storage and regulator submission are not connected. Coverage checks are organisational aids and do not certify compliance.</p></div><div class="form-footer"><button class="btn" data-action="close-modal">Got it</button></div>`);return;}
if(action==='settings'){openModal('Your workspace, your records.',`<p>Your data stays on this device. Browser storage may be cleared by your browser settings or when using private browsing.</p><div class="status-box"><h3>Keep a copy.</h3><p>Export the project records as JSON, and download original documents separately. The JSON backup includes project metadata, actions and activity; it excludes file binaries.</p></div><div class="form-footer"><button class="btn secondary" data-action="close-modal">Close</button><button class="btn" data-action="backup">${icon('download')}Export records</button></div>`);return;}
});
document.addEventListener('input',ev=>{
if(ev.target.id==='search'){search=ev.target.value;applySearch();}
if(ev.target.hasAttribute('data-calculator')){const projects=+document.querySelector('#calc-projects').value,hours=+document.querySelector('#calc-hours').value,rate=+document.querySelector('#calc-rate').value;document.querySelector('#out-projects').textContent=projects;document.querySelector('#out-hours').textContent=hours+' hours';document.querySelector('#out-rate').textContent='£'+rate+' / hour';document.querySelector('#calc-result').textContent=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(projects*hours*rate);}
});
document.addEventListener('change',ev=>{if(ev.target.id==='project-focus'){selected=ev.target.value;search='';filter='All';save();render();}});
document.addEventListener('keydown',ev=>{if(ev.target.matches('[data-action=workflow]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(ev.key)){ev.preventDefault();const i=Number(ev.target.dataset.step),next=ev.key==='Home'?0:ev.key==='End'?2:(i+(['ArrowRight','ArrowDown'].includes(ev.key)?1:2))%3;const tab=app.querySelector(`[data-action="workflow"][data-step="${next}"]`);tab.click();tab.focus();}});

document.addEventListener('submit',async ev=>{
const form=ev.target.closest('[data-form]');if(!form)return;ev.preventDefault();const data=Object.fromEntries(new FormData(form));
if(form.dataset.form==='project'){try{const p=createProject(data);state.projects.unshift(p);selected=p.id;save();modal.close();location.hash='#/app/evidence';render();toast('Project created. Add documents to start your evidence register.');}catch(err){toast(err.message);}return;}
if(form.dataset.form==='action'){
 if(data.status==='Resolved'&&!data.note.trim()){form.querySelector('#form-error').textContent='Record a review note or decision before resolving this action.';return;}
 const p=project();let x=p.issues.find(x=>x.id===form.dataset.id);if(x){x.owner=data.owner.trim()||'Unassigned';x.status=data.status;x.note=data.note.trim();log(p,`Review action updated: ${x.title} · ${x.status} · ${x.owner}`);}else{x={id:uid(),...data,owner:data.owner.trim()||'Unassigned',document:'Submission pack',reference:'Manual reviewer action'};p.issues.unshift(x);log(p,`Review action created: ${x.title}`);}save();modal.close();render();toast('Review action saved.');return;}
if(form.dataset.form==='document'){const p=project(),d=p.documents.find(x=>String(x.id)===form.dataset.id);d.category=data.category;d.owner=data.owner.trim();d.revision=data.revision.trim();log(p,`Document record updated: ${d.name} · revision ${d.revision}`);save();modal.close();render();toast('Document record updated.');return;}
if(form.dataset.form==='upload'){
 const files=[...form.querySelector('#upload-files').files],error=form.querySelector('#form-error'),submit=form.querySelector('[type=submit]');
 if(!files.length){error.textContent='Choose at least one file.';return;}
 const invalid=files.find(f=>f.size>10*1024*1024||!(/\.(pdf|docx|xlsx|csv|txt|png|jpe?g)$/i.test(f.name)));
 if(invalid){error.textContent=`${invalid.name}: use a supported file type up to 10 MB.`;return;}
 submit.disabled=true;submit.textContent='Saving documents…';const p=project();let added=0;
 try{for(const f of files){const id=uid();await fileStore('readwrite',id,f);p.documents.push({id,name:f.name,category:data.category,owner:data.owner.trim()||'You',revision:data.revision.trim()||'P01',date:new Date().toISOString(),size:f.size,sample:false});log(p,`Document added: ${f.name} · ${data.category}`);added++;}save();modal.close();render();toast(`${added} document${added===1?'':'s'} added to the register.`);}catch{save();error.textContent=`${added?`${added} files saved. `:''}Unable to save more files in this browser. Check storage availability.`;submit.disabled=false;submit.textContent='Add to register';}return;}
});
route();
